#include <stdio.h>
#include <limits.h>

int main(void) {
    int R, N;
    if (scanf("%d %d", &R, &N) != 2) return 0;

    int cheapest[101];
    for (int i = 1; i <= 100; i++) cheapest[i] = INT_MAX;

    for (int i = 0; i < N; i++) {
        int type, price;
        scanf("%d %d", &type, &price);
        if (price < cheapest[type]) cheapest[type] = price;
    }

    int prices[100], count = 0;
    for (int i = 1; i <= 100; i++) {
        if (cheapest[i] != INT_MAX) prices[count++] = cheapest[i];
    }

    for (int i = 0; i < count; i++) {
        for (int j = i + 1; j < count; j++) {
            if (prices[j] < prices[i]) {
                int temp = prices[i];
                prices[i] = prices[j];
                prices[j] = temp;
            }
        }
    }

    int spent = 0, answer = 0;
    for (int i = 0; i < count; i++) {
        if (spent + prices[i] > R) break;
        spent += prices[i];
        answer++;
    }

    printf("%d\n", answer);
    return 0;
}
